def finish_capture():
 if not SUMMARY['completed'] and not SUMMARY['failures']:SUMMARY['failures'].append('stopped before endpoint without a handled guard')
 if SUMMARY['new_threads']:SUMMARY['failures'].append('unexpected new thread')
